(129, 1, '2026-10-07 20:12:01', '2026-10-07 20:12:01', '<!-- wp:group {\"style\":{\"color\":{\"background\":\"#cfe8f7\"},\"border\":{\"radius\":{\"topLeft\":\"30px\",\"topRight\":\"30px\",\"bottomLeft\":\"30px\",\"bottomRight\":\"30px\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-background\" style=\"border-top-left-radius:30px;border-top-right-radius:30px;border-bottom-left-radius:30px;border-bottom-right-radius:30px;background-color:#cfe8f7\"><!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">🥱 <strong>For Those Energy-Draining Days</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong>HABITQUEST GUIDEBOOK</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">Use these when you\'re busy, bored or losing momentum. Pick one \"power-up\" &amp; try it for 3 days.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {\"height\":\"47px\"} -->\n<div style=\"height:47px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:shortcode -->\n[hq_tip_box]\n<!-- /wp:shortcode -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"},\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"right\":\"0\"}}},\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center has-large-font-size\" style=\"padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><strong>CHOOSE YOUR MOOD</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\"}}}} -->\n<div class=\"wp-block-columns\" style=\"padding-top