g -->\n\n<!-- wp:list {\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|70\",\"left\":\"var:preset|spacing|70\"}}}} -->\n<ul style=\"padding-right:var(--wp--preset--spacing--70);padding-left:var(--wp--preset--spacing--70)\" class=\"wp-block-list\"><!-- wp:list-item -->\n<li>Put extra effort to surpass the goal.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Plan some rest days to reset.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Don\'t run god mode all month.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {\"height\":\"35px\"} -->\n<div style=\"height:35px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:shortcode -->\n[hq_tips_sections]\n<!-- /wp:shortcode -->', 'Tips', '', 'publish', 'closed', 'closed', '', 'tips', '', '', '2026-10-08 13:32:19', '2026-10-08 13:32:19', '', 0, 'http://localhost/habitquest/?page_id=129', 0, 'page', '', 0),
